WFJ.Data.add("book", {
  ["a11a16671527d47a"] = { "buon numero, ma non sono né ben armati né organizzati. Una piccola dimostrazione di forza dovrebbe bastare e avanzare per affrontare la minaccia che rappresentano.", "." },
  ["a134a0dba8becbb2"] = { "Fa piacere sapere che qualcuno della famiglia di Jen'shan viene nella Valle a mettere alla prova la sua abilità. Jen'shan non vede l'ora!\n\nNon serve che io ti dica quanta forza e astuzia hai nella caccia: tu lo sai già. Il compito di Jen'shan è dirti come averne ancora di più.\n\nTrovi Jen'shan nella ⟦Valley of Trials=Valle delle Sfide⟧. Lei ti insegna bene. Ti insegna a domare le bestie più grandi, e tante altre cose.\n\n-Jen'shan, istruttrice dei cacciatori", "." },
  ["a159b9e9848cca25"] = { "Salute a te, Ello Ebonlocke, sindaco di ⟦Darkshire=Borgoscuro⟧. Temo di avere notizie per la tua città. Notizie gravi.\n\nVedi, io sono un creatore. Ho ingannato chi ti porta questo biglietto perché mi aiutasse nella mia ultima e più terribile creazione: un mostro di carne, ossa e metallo contorto! Mentre leggi, probabilmente è fuori dalla mia umile dimora, digrigna i denti e aspetta un mio cenno per partire e fare strage.\n\nMa lo saprai molto presto.\n\n-L'Imbalsamatore", "." },
  ["a19d919b250f17c2"] = { "RAPPORTO: coboldi\n\nL'attività dei coboldi è aumentata nei dintorni della ⟦Northshire Valley=Valle della Contea del Nord⟧. Si accampano a nord dell'abbazia e dentro la ⟦Echo Ridge Mine=Miniera Cresta dell'Eco⟧ in numero allarmante. Ho radunato paladini, guerrieri e altra gente del posto perché mi aiutino a liberarci di quei parassiti.\n\nLe cose procedono bene. Darò aggiornamenti quando servirà.", "." },
  ["a1e4679c54bc1bd3"] = { "in realtà di una manifestazione fisica dei poteri del Signore delle Acque, un potente elementale dei mari. Come e perché un oggetto simile sia sfuggito al controllo del Signore delle Acque e sia finito nelle mani dei troll è un'altra questione, che va oltre le mie conoscenze.\n\nIL TIDEBEARER\n\nCome il moto delle maree da cui prende il nome, la ⟦Stone of the Tides=Pietra delle Maree⟧ entrava nel mondo dei troll e ne usciva, senza mai restare nelle loro mani per più di una generazione alla volta.", "." },
  ["a1e6a01d84c8a4dd"] = { "L'armata di Proudmoore rappresentava una seria minaccia per la stabilità della regione. Celebre eroe della Seconda Guerra, il padre di Jaina era un acerrimo nemico dell'⟦Horde=Orda⟧ ed era deciso a distruggere Durotar prima che gli orchi potessero mettere radici in quella terra.", "." },
})
